(function(){'use strict';const THEME_KEY='meme-explorer-theme';function getPreferredTheme(){const stored=localStorage.getItem(THEME_KEY);if(stored){return stored;}return window.matchMedia('(prefers-color-scheme:dark)').matches ? 'dark':'light';}function applyTheme(theme){document.documentElement.setAttribute('data-theme',theme);updateToggleIcon(theme);}function updateToggleIcon(theme){const toggle=document.getElementById('theme-toggle');if(toggle){toggle.textContent=theme==='dark' ? '☀️':'🌙';toggle.setAttribute('aria-label',`Switch to ${theme==='dark' ? 'light':'dark'}mode`);}}function toggleTheme(){const current=document.documentElement.getAttribute('data-theme')|| getPreferredTheme();const next=current==='dark' ? 'light':'dark';localStorage.setItem(THEME_KEY,next);applyTheme(next);if(typeof gtag !=='undefined'){gtag('event','theme_change',{theme:next});}}function initTheme(){const theme=getPreferredTheme();applyTheme(theme);window.matchMedia('(prefers-color-scheme:dark)').addEventListener('change',(e)=>{if(!localStorage.getItem(THEME_KEY)){applyTheme(e.matches ? 'dark':'light');}});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initTheme);}else{initTheme();}window.toggleTheme=toggleTheme;})();